import {IssuesList} from './components/IssuesList'
import {PullRequestsList} from './components/PullRequestsList'
import {DashboardAgentsList} from './components/DashboardAgentsList'

export interface DashboardListsProps {
  userDisplayLogin: string
  currentUserId?: number
  showAgentsModule?: boolean
  showCopilotChatActions?: boolean
}

export function DashboardLists({
  userDisplayLogin,
  currentUserId,
  showAgentsModule = false,
  showCopilotChatActions = false,
}: DashboardListsProps) {
  return (
    <>
      {showAgentsModule ? <DashboardAgentsList currentUserId={currentUserId} /> : null}

      <PullRequestsList userDisplayLogin={userDisplayLogin} showCopilotChatActions={showCopilotChatActions} />

      <IssuesList userDisplayLogin={userDisplayLogin} showCopilotChatActions={showCopilotChatActions} />
    </>
  )
}
