import {AgentsList} from './AgentsList'
import {ConsecutiveCAPI401sProvider} from '@github-ui/agent-sessions/contexts/ConsecutiveCAPI401sContext'
import {CurrentUserProvider} from '@github-ui/agent-sessions/contexts/CurrentUserContext'
import {dashboardLocalStorage} from '../utils/dashboard-local-storage'
import {AgentQueryQualifier} from '../types'
import {CopilotChatProvider} from '@github-ui/copilot-chat/CopilotChatContext'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {useCopilotChatPayloadQuery} from '@github-ui/global-copilot-menu/hooks/useCopilotChatPayloadQuery'
import {useSSOChangeDetection} from '@github-ui/agent-sessions/hooks/useSSOChangeDetection'
import {
  DashboardListView,
  DashboardListViewHeader,
  DashboardListViewHeaderTitle,
  DashboardListViewItems,
  DashboardListViewItemsSkeletonLoader,
} from './DashboardListView'
import {Stack} from '@primer/react'

const LIST_TITLE = 'Agent sessions'

function AgentsListWithSSO() {
  useSSOChangeDetection()
  const defaultInitialQualifiers = [AgentQueryQualifier.Open]

  return (
    <AgentsList
      analyticsCategory="productivity_dashboard"
      initialResultCount={dashboardLocalStorage.getAgentResultCount() ?? undefined}
      initialQueryQualifiers={dashboardLocalStorage.getAgentQueryQualifiers() ?? defaultInitialQualifiers}
      persistResultCount={count => dashboardLocalStorage.setAgentResultCount(count)}
      persistQueryQualifiers={qualifiers => dashboardLocalStorage.setAgentQueryQualifiers(qualifiers)}
      title={LIST_TITLE}
      showViewAll
      showFilterMenu
      emptyPlaceholder="Start an agent session to create new work or iterate on an existing project."
      enableEmptyListAction
    />
  )
}

interface DashboardAgentsListProps {
  currentUserId?: number
}

export function DashboardAgentsList({currentUserId}: DashboardAgentsListProps) {
  const chatPayload = useCopilotChatPayloadQuery()

  const currentUser = currentUserId
    ? {id: currentUserId, login: chatPayload?.currentUserLogin ?? '', primaryAvatarUrl: ''}
    : undefined

  if (!chatPayload) {
    return (
      <DashboardListView>
        <DashboardListViewHeader>
          <DashboardListViewHeaderTitle headingLevel="h3">
            <Stack direction="horizontal" gap="condensed" align="center">
              {LIST_TITLE}
            </Stack>
          </DashboardListViewHeaderTitle>
        </DashboardListViewHeader>
        <DashboardListViewItems>
          <DashboardListViewItemsSkeletonLoader />
        </DashboardListViewItems>
      </DashboardListView>
    )
  }

  return (
    <CurrentUserProvider currentUser={currentUser} currentUserIsSessionOwner>
      <ConsecutiveCAPI401sProvider>
        <CopilotChatProvider
          threadId={null}
          workerPath={chatPayload.findFileWorkerPath}
          refs={chatPayload.refs ?? []}
          mode="assistive"
          ssoOrganizations={chatPayload.ssoOrganizations ?? []}
          copilotChatPayload={chatPayload}
        >
          <AgentsListWithSSO />
        </CopilotChatProvider>
      </ConsecutiveCAPI401sProvider>
    </CurrentUserProvider>
  )
}
