// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {getPullRequestStateIcon} from '@github-ui/list-view-items-issues-prs/StateIcon'
import {CommentIcon, CopilotIcon, VscodeIcon} from '@primer/octicons-react'

import {RelativeTime} from '@primer/react'
import {useMemo} from 'react'
import type {DashboardPullRequest} from '../types'
import {
  DashboardListItem,
  DashboardListItemTitle,
  DashboardListItemDescription,
  DashboardListItemLeadingVisual,
  DashboardListItemActions,
  DashboardListItemTrailingActionsMenu,
  DashboardListItemStatus,
} from './DashboardListView'
import {useOpenCopilotChat} from '../hooks/useOpenCopilotChat'
import styles from '../DashboardLists.module.css'
import viewStyles from './DashboardListView.module.css'
import {useDashboardAnalytics} from '../hooks/useDashboardAnalytics'
import {useVSCodePullRequestUrl} from '../hooks/useVSCodePullRequestUrl'
import {attemptOpenUrlWithFallback} from '../utils/attempt-open-url-with-fallback'
import {isFeatureEnabled} from '@github-ui/feature-flags'

const DASHBOARD_PULL_REQUEST_LIST_ITEM_CHAT_ACTION = 'dashboard-pull-request-list-item-chat-action'

interface PullRequestListItemProps {
  pullRequest: DashboardPullRequest
  onTitleClick: () => void
  showCopilotChatActions?: boolean
}

export function PullRequestListItem({pullRequest, onTitleClick, showCopilotChatActions}: PullRequestListItemProps) {
  const {openCopilotChatWithPullRequest} = useOpenCopilotChat()
  const {repoNameWithOwner} = pullRequest
  const {ownerLogin, name} = repoNameWithOwner

  const {
    icon: Icon,
    color,
    description,
  } = useMemo(() => {
    let pullRequestStateString = 'OPEN'
    if (pullRequest.isDraft) pullRequestStateString = 'DRAFT'
    if (pullRequest.inMergeQueue) pullRequestStateString = 'IN_MERGE_QUEUE'

    return getPullRequestStateIcon(pullRequestStateString)
  }, [pullRequest.inMergeQueue, pullRequest.isDraft])

  const {sendDashboardClickAnalyticsEvent} = useDashboardAnalytics()
  const onSelectOpenInCopilotChat = () => {
    openCopilotChatWithPullRequest(pullRequest, DASHBOARD_PULL_REQUEST_LIST_ITEM_CHAT_ACTION)
    sendDashboardClickAnalyticsEvent('open_pull_request_in_copilot_chat')
  }

  const showOpenPullRequestInVSCodeAction = isFeatureEnabled('dashboard_lists_open_pr_in_vscode')

  const vsCodePullRequestUrl = useVSCodePullRequestUrl({
    owner: ownerLogin,
    repo: name,
    pullRequestNumber: pullRequest.number,
  })

  const onClickOpenPullRequestInVSCode = () => {
    sendDashboardClickAnalyticsEvent('open_pull_request_in_vscode')

    attemptOpenUrlWithFallback(vsCodePullRequestUrl, `${ownerLogin}/${name}`)
  }

  const createdTime = new Date(pullRequest.createdAt).setSeconds(0, 0)
  const updatedTime = new Date(pullRequest.updatedAt).setSeconds(0, 0)
  const timestampLabel = createdTime !== updatedTime ? 'Updated ' : 'Created '

  return (
    <DashboardListItem className={viewStyles.fadeIn}>
      <DashboardListItemLeadingVisual>
        <div style={{color}}>
          <Icon aria-label={description} fill={color} />
        </div>
      </DashboardListItemLeadingVisual>
      <DashboardListItemTitle href={pullRequest.permalink} onClick={onTitleClick}>
        {pullRequest.title}
      </DashboardListItemTitle>
      <DashboardListItemDescription>
        {`${ownerLogin}/${name}#${pullRequest.number} · Opened by ${pullRequest.author} · `}
        {timestampLabel}
        <RelativeTime format="relative" datetime={pullRequest.updatedAt} />
        {pullRequest.assignedToCopilot ? (
          <DashboardListItemStatus>
            <span className={styles.assignedToCopilotStatus}>
              <CopilotIcon size={18} className={styles.copilotIcon} />
              <span className={styles.assignedToCopilotText}>Assigned to Copilot</span>
            </span>
          </DashboardListItemStatus>
        ) : null}
      </DashboardListItemDescription>
      <DashboardListItemActions>
        {pullRequest.commentCount > 0 && (
          <div>
            <div
              className={!pullRequest.readByCurrentUser ? styles.commentIconWithIndicator : styles.commentIcon}
              data-testid={!pullRequest.readByCurrentUser ? 'activity-indicator' : undefined}
            >
              <CommentIcon size={16} data-testid="comment-icon" /> <span>{pullRequest.commentCount}</span>
            </div>
            <span className="sr-only">{pullRequest.commentCount === 1 ? ' comment' : ' comments'}</span>
            {!pullRequest.readByCurrentUser && <span className="sr-only">New activity.</span>}
          </div>
        )}
      </DashboardListItemActions>

      {showCopilotChatActions || showOpenPullRequestInVSCodeAction ? (
        <DashboardListItemTrailingActionsMenu aria-label="Pull request actions">
          {showCopilotChatActions && (
            <DashboardListItemTrailingActionsMenu.Item
              icon={CopilotIcon}
              label="Open in Copilot Chat"
              onClick={onSelectOpenInCopilotChat}
            />
          )}
          {showOpenPullRequestInVSCodeAction && (
            <DashboardListItemTrailingActionsMenu.Item
              icon={VscodeIcon}
              label="Open pull request in VS Code"
              onClick={onClickOpenPullRequestInVSCode}
            />
          )}
        </DashboardListItemTrailingActionsMenu>
      ) : null}
    </DashboardListItem>
  )
}
