import {
  DashboardListView,
  DashboardListViewHeader,
  DashboardListViewHeaderTitle,
  DashboardListViewHeaderMetadata,
  DashboardListViewItems,
  DashboardListItem,
  DashboardListItemTitle,
  DashboardListViewItemsSkeletonLoader,
} from './DashboardListView'
import {useQueries} from '@github-ui/react-query'
import {useClickAnalytics, useAnalytics} from '@github-ui/use-analytics'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {VIEW_NAMES} from '@github-ui/issue-url-helper/constants/view-constants'
import {useCallback, useMemo} from 'react'
import type {DashboardIssue} from '../types'
import {QueryQualifier, DashboardIssueValidator, MaxAgeQualifier, getMaxAgeValue} from '../types'
import {dashboardLocalStorage, useDashboardStorage} from '../utils/dashboard-local-storage'
import {dedupeById} from '../utils/dedupe-by-id'
import {IssueListItem} from './IssueListItem'
import {ListActionMenu} from './ListActionMenu'
import {AlertIcon} from '@primer/octicons-react'
import {Link, Stack} from '@primer/react'
import styles from './DashboardListView.module.css'
import {useLocalStorageCache} from '../hooks/useLocalStorageCache'
import {issuesBaseQuery} from './issues-constants'
import {createPersister} from '@github-ui/react-query-persister'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {MAX_AGE_MENU_ITEMS, ONE_MIN} from '../constants'

interface IssuesListProps {
  userDisplayLogin: string
  loadingState?: React.ReactElement
  showCopilotChatActions?: boolean
}

const DEFAULT_RESULT_COUNT = 3
const DEFAULT_QUERY_QUALIFIERS = [QueryQualifier.Assigned, QueryQualifier.Involves]
const DEFAULT_LOADING_STATE = <DashboardListViewItemsSkeletonLoader />

const noop = () => undefined

export function IssuesList({
  userDisplayLogin,
  loadingState = DEFAULT_LOADING_STATE,
  showCopilotChatActions,
}: IssuesListProps) {
  const {data} = useDashboardStorage()
  const queryQualifiers = data?.issueQueryQualifiers ?? DEFAULT_QUERY_QUALIFIERS
  const resultCount = data?.issueResultCount ?? DEFAULT_RESULT_COUNT
  const defaultMaxAgeQualifier = isFeatureEnabled('dashboard_lists_max_age_filter')
    ? MaxAgeQualifier.OneYear
    : MaxAgeQualifier.NoMax
  const maxAgeQualifier = data?.issueMaxAgeQualifier ?? defaultMaxAgeQualifier
  const {sendAnalyticsEvent} = useAnalytics()
  const dashboard_indexeddb_caching = isFeatureEnabled('dashboard_indexeddb_caching')
  const {getLocalStorageValue, setLocalStorageValue: _setLocalStorageValue} =
    useLocalStorageCache<DashboardIssue[]>('dashboard-issues')
  // When feature flag is off, use localStorage
  const setLocalStorageValue = dashboard_indexeddb_caching ? noop : _setLocalStorageValue
  // eslint-disable-next-line react-hooks/purity -- using a memo to lock in the value
  const now = useMemo(() => Date.now(), [])

  const setIssueQueryQualifiers = (queries: QueryQualifier[]) => {
    dashboardLocalStorage.setIssueQueryQualifiers(queries)
  }

  const setIssueResultCount = (count: number) => {
    dashboardLocalStorage.setIssueResultCount(count)
  }

  const setIssueMaxAgeQualifier = (qualifier: MaxAgeQualifier) => {
    dashboardLocalStorage.setIssueMaxAgeQualifier(qualifier)
  }

  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const onViewAllIssues = useCallback(() => {
    sendClickAnalyticsEvent({category: 'productivity_dashboard', action: 'click.view_all_issues'})
  }, [sendClickAnalyticsEvent])
  const onTitleClick = useCallback(() => {
    sendClickAnalyticsEvent({category: 'productivity_dashboard', action: 'click.navigate_to_issue'})
  }, [sendClickAnalyticsEvent])

  const persister = useMemo(
    () =>
      createPersister({
        validator: DashboardIssueValidator,
        sendAnalyticsEvent,
        enabled: dashboard_indexeddb_caching,
      }),
    [sendAnalyticsEvent, dashboard_indexeddb_caching],
  )

  const {
    isLoading,
    data: issues,
    isError,
  } = useQueries({
    queries: queryQualifiers.map(qualifier => {
      const queryKey = [issuesBaseQuery, qualifier, userDisplayLogin, maxAgeQualifier]
      const localCacheKey = queryKey.join('::')

      return {
        queryKey,
        queryFn: async () => {
          const ageValue = getMaxAgeValue(maxAgeQualifier)
          const ageQualifier = ageValue ? ` created:>=${ageValue}` : ''

          const response = await reactFetchJSON(
            `/productivity_dashboard/issues?q=${encodeURIComponent(
              `${issuesBaseQuery} ${qualifier}:${userDisplayLogin}${ageQualifier}`,
            )}`,
          )

          if (!response.ok) throw new Error(`HTTP ${response.status}`)

          const payload = (await response.json()).data as DashboardIssue[]
          setLocalStorageValue(localCacheKey, payload)
          return payload
        },
        staleTime: ONE_MIN,
        persister,
        initialData: dashboard_indexeddb_caching ? undefined : () => getLocalStorageValue(localCacheKey),
        initialDataUpdatedAt: dashboard_indexeddb_caching ? undefined : now - ONE_MIN, // triggers refetch immediately
      }
    }),
    combine: results => {
      return {
        data: dedupeById(results.flatMap(result => result.data || []))
          .sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime())
          .slice(0, resultCount),
        isLoading: results.some(result => result.isLoading),
        isError: results.some(result => result.isError),
      }
    },
  })

  return (
    <DashboardListView>
      <DashboardListViewHeader>
        <DashboardListViewHeaderTitle headingLevel="h3">
          <Stack direction="horizontal" gap="condensed" align="center">
            Issues
          </Stack>
        </DashboardListViewHeaderTitle>
        <DashboardListViewHeaderMetadata>
          <Link href="/issues" onClick={onViewAllIssues}>
            View all<span className="sr-only"> issues</span>
          </Link>
          <ListActionMenu
            setQueryQualifiers={setIssueQueryQualifiers}
            queryQualifiers={queryQualifiers}
            setResultCount={setIssueResultCount}
            resultCount={resultCount}
            label="Issue options"
            filterGroupHeading="Issues to include"
            menuItems={[
              {label: VIEW_NAMES.assignedToMe, value: QueryQualifier.Assigned},
              {label: VIEW_NAMES.involves, value: QueryQualifier.Involves},
            ]}
            selectedMaxAgeQualifier={maxAgeQualifier}
            setMaxAgeQualifier={setIssueMaxAgeQualifier}
            maxAgeMenuItems={MAX_AGE_MENU_ITEMS}
            analyticsEventType={'issues_options.save'}
            analyticsTarget={'DASHBOARD_ISSUES_ACTION_MENU'}
            analyticsCategory="productivity_dashboard"
          />
        </DashboardListViewHeaderMetadata>
      </DashboardListViewHeader>
      <DashboardListViewItems>
        {isError ? (
          <DashboardListItem className={styles.emptyItem}>
            <AlertIcon className={styles.noItemsIcon} />

            <DashboardListItemTitle as="p" className={styles.emptyTitle}>
              Unable to load issues, try again later.
            </DashboardListItemTitle>
          </DashboardListItem>
        ) : isLoading ? (
          loadingState
        ) : issues.length === 0 ? (
          <DashboardListItem className={styles.emptyItem}>
            <DashboardListItemTitle as="p" className={styles.emptyTitle}>
              No issues found, try a different filter.
            </DashboardListItemTitle>
          </DashboardListItem>
        ) : (
          issues.map(issue => (
            <IssueListItem
              key={issue.id}
              issue={issue}
              onTitleClick={onTitleClick}
              showCopilotChatActions={showCopilotChatActions}
            />
          ))
        )}
      </DashboardListViewItems>
    </DashboardListView>
  )
}
