import {useMemo} from 'react'

type Props = {
  owner: string
  repo: string
  pullRequestNumber: number
}
const vscodeUrl = `vscode://github.vscode-pull-request-github/open-pull-request-webview`

export function useVSCodePullRequestUrl({owner, repo, pullRequestNumber}: Props) {
  return useMemo(() => {
    const payload = {owner, repo, pullRequestNumber}
    const encodedPayload = encodeURIComponent(JSON.stringify(payload))

    return `${vscodeUrl}?${encodedPayload}`
  }, [owner, pullRequestNumber, repo])
}
